-- Reviewed starter discussions; fictional display personas, no auth accounts,
-- no fabricated replies, likes, visits, historical timestamps or badges.
-- Run only after 20260930121000. Re-running never changes an existing thread
-- or removes a user's real replies/moderation decisions.
begin;
insert into public.forum_topics(id, seed_key, slug, title, content, author_name, country_slug, author_id, category, status, is_paywalled)
select v.id::uuid, v.seed_key, v.slug, v.title, v.content, v.author_name, v.country_slug,
  null, 'Ülke Bazlı Sorunlar', 'published', false
from (values
  ('f09a2026-0930-4000-8000-000000000001', 'starter-20260930-01', 'starter-20260930-01', 'İstanbul’da bir gününüz olsa hangi rotayı yürürdünüz?', 'Tarihi yarımadayı mı seçersiniz, yoksa vapurla Kadıköy’e geçip sokak aralarını mı gezersiniz? Arabasız, bol yürümeli bir gün planlamak istiyorum. Sizin olmazsa olmaz durağınız neresi?', 'yoldaki.deniz', 'turkiye'),
  ('f09a2026-0930-4000-8000-000000000002', 'starter-20260930-02', 'starter-20260930-02', 'Bodrum için araba şart mı?', 'Bodrum merkezde kalıp birkaç farklı koya gitmek isteyen biri için dolmuş yeterli olur mu? Her gün araç kiralamak yerine iki gün kiralama fikrine nasıl bakıyorsunuz? Ulaşımı kolay koy önerilerini de bekliyorum.', 'seda.rota', 'turkiye'),
  ('f09a2026-0930-4000-8000-000000000003', 'starter-20260930-03', 'starter-20260930-03', 'Kapadokya’da balon dışında ne yapılır?', 'Kapadokya denince hep balon fotoğrafları çıkıyor. Ben biraz vadilerde yürüyüp küçük yerleri keşfetmek istiyorum. İki günlük sakin bir program için nereden başlamalıyım?', 'mert.yoldefteri', 'turkiye'),
  ('f09a2026-0930-4000-8000-000000000004', 'starter-20260930-04', 'starter-20260930-04', 'Tek sırt çantasıyla üç günlük gezi: neleri almıyorsunuz?', 'Kısa gezilerde çantayı yine gereğinden fazla dolduruyorum. Sizin evde bırakmayı öğrendiğiniz şeyler neler? Küçük bir çantayla rahat etmenin pratik püf noktalarını konuşalım.', 'gezgin.ada', 'turkiye'),
  ('f09a2026-0930-4000-8000-000000000005', 'starter-20260930-05', 'starter-20260930-05', 'Roma’ya ilk kez gidecek birine hangi mahalleyi önerirsiniz?', 'Merkezde olmak güzel ama bütün bütçeyi konaklamaya ayırmak istemiyorum. Akşam yürüyüş yapılabilen, toplu taşımaya yakın mahalleler hangileri? Otel ismi yerine bölge önerileri de çok işime yarar.', 'elif.izler', 'italya'),
  ('f09a2026-0930-4000-8000-000000000006', 'starter-20260930-06', 'starter-20260930-06', 'Tokyo için beş gün çok mu az?', 'Şehri koşturarak gezmek istemiyorum. Beş günün birini yakın bir yere ayırmak mı daha mantıklı, yoksa tamamını Tokyo’da geçirmek mi? İlk kez gidecek biri için günlük bölgeleri nasıl ayırırdınız?', 'cem.pusula', 'japonya'),
  ('f09a2026-0930-4000-8000-000000000007', 'starter-20260930-07', 'starter-20260930-07', 'Tiran’dan başlayınca Berat mı İşkodra mı?', 'Arnavutluk için kısa bir rota üzerine düşünüyorum. Tiran’a ek olarak tek bir şehir seçmek gerekse hangisini seçerdiniz? Manzara, yürüyüş ve yerel yemek önceliğim; tempoyu sakin tutmak istiyorum.', 'melis.biryerlerde', 'arnavutluk'),
  ('f09a2026-0930-4000-8000-000000000008', 'starter-20260930-08', 'starter-20260930-08', 'Prizren’de yavaş bir gün nasıl geçer?', 'Bir şehri kahve molalarıyla, yürüyerek tanımayı seviyorum. Prizren’de kaleye çıkış dışında hangi sokaklar ve duraklar bir güne eklenebilir? Fotoğraf çekmek için sevdiğiniz saatleri de paylaşın.', 'arda.kucukmolalar', 'kosova'),
  ('f09a2026-0930-4000-8000-000000000009', 'starter-20260930-09', 'starter-20260930-09', 'Saraybosna ve Mostar aynı kısa geziye sığar mı?', 'Üç günlük bir plan için iki şehri birleştirmek yorucu olur mu? Mostar’a günübirlik gidip dönmek yerine bir gece kalmayı önerir misiniz? Ulaşım ve zaman kullanımı konusunda fikirlerinizi merak ediyorum.', 'ece.kesifnotu', 'bosna-hersek'),
  ('f09a2026-0930-4000-8000-000000000010', 'starter-20260930-10', 'starter-20260930-10', 'Berlin’de müzeler mi mahalle gezileri mi?', 'İlk Berlin gezisinde her şeyi listeye yazınca günler yetmiyor. Üç gün için müze ve mahalle yürüyüşü dengesini nasıl kurardınız? Daha az durakla daha çok vakit geçirmek isteyenlere öneriniz var mı?', 'berk.yolarkadasi', 'almanya'),
  ('f09a2026-0930-4000-8000-000000000011', 'starter-20260930-11', 'starter-20260930-11', 'Paris’te yağmurlu bir gün için alternatif plan', 'Açık hava planı yağmura takılırsa bütün günü alışveriş merkezinde geçirmek istemem. Küçük müzeler, kapalı pasajlar veya uzun oturulabilecek semtler için önerileriniz neler?', 'duru.rotam', 'fransa'),
  ('f09a2026-0930-4000-8000-000000000012', 'starter-20260930-12', 'starter-20260930-12', 'Bali’de tek bölgede kalmak mı, konaklamayı bölmek mi?', 'Bir haftalık gezi için her iki günde bir valiz toplamak istemiyorum. Ubud ile sahil tarafını birleştirirken siz nasıl bir denge kurardınız? Trafikte çok zaman kaybetmeden plan yapmaya çalışıyorum.', 'can.dunyayadogru', 'endonezya'),
  ('f09a2026-0930-4000-8000-000000000013', 'starter-20260930-13', 'starter-20260930-13', 'Londra’da ücretsiz gezi durakları neler?', 'Müze ve park ağırlıklı bir rota hazırlamak istiyorum. Aynı gün içinde birbirine yakın hangi ücretsiz duraklar birleştirilebilir? Yürümeyi seviyorum; güzel bir mola noktası da eklerseniz harika olur.', 'aylin.sehirarasi', 'birlesik-krallik'),
  ('f09a2026-0930-4000-8000-000000000014', 'starter-20260930-14', 'starter-20260930-14', 'Tiflis’te hangi bölgeden yürümeye başlamalı?', 'Eski şehir, nehir çevresi ve manzara noktalarını koşturmadan görmek için bir günlük yürüyüş rotasını nasıl kurardınız? Yokuşları da hesaba katmak istiyorum. Aklınıza gelen küçük durakları yazın.', 'umut.gunbatimi', 'gurcistan'),
  ('f09a2026-0930-4000-8000-000000000015', 'starter-20260930-15', 'starter-20260930-15', 'Arnavutluk sahilleri için sakin rota önerisi', 'Kalabalık plajlardan çok küçük koylar ve yürüyüş yolları ilgimi çekiyor. Sahil boyunca sürekli yer değiştirmek yerine bir bölgede birkaç gün kalmak için nerelere bakmalıyım? Arabasız seçenekleri de merak ediyorum.', 'selin.yolcizgisi', 'arnavutluk')
) as v(id, seed_key, slug, title, content, author_name, country_slug)
on conflict (seed_key) where seed_key is not null do nothing;
commit;
